import heapq

def shortest_path(edges, start, end):
    # If start and end are the same node
    if start == end:
        return (0, [start])

    # Build the adjacency list and check for negative weights
    graph = {}
    for u, v, w in edges:
        if w < 0:
            raise ValueError("Edge weights cannot be negative.")
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))
        # Ensure the destination node is in the graph as a key as well
        if v not in graph:
            graph[v] = []

    # If start or end nodes are not in the graph at all
    if start not in graph or end not in graph:
        return (None, None)

    # Priority queue stores: (current_distance, current_node, path_so_far)
    pq = [(0, start, [start])]

    # Track the shortest distance found to each node to avoid redundant processing
    min_distances = {start: 0}

    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        # If we reached the destination, return the result
        if current_node == end:
            return (current_distance, path)

        # If we found a longer path to the current node than already recorded, skip
        if current_distance > min_distances.get(current_node, float('inf')):
            continue

        # Explore neighbors
        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            # If a shorter path to the neighbor is found
            if distance < min_distances.get(neighbor, float('inf')):
                min_distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor, path + [neighbor]))

    # If the priority queue is exhausted and we haven't returned, no path exists
    return (None, None)
